#!/usr/bin/env python3
"""Extract a bounded real native shared-pad fixture, retaining exact source identities."""
import argparse,hashlib,json,shutil
from pathlib import Path
ap=argparse.ArgumentParser();ap.add_argument('--model',type=Path,required=True);ap.add_argument('--out',type=Path,required=True);ap.add_argument('--pad',default='U14.4');a=ap.parse_args();sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();m=json.loads(a.model.read_text());cs=[c for c in m['contacts']if c['key']==a.pad];uids={c['uuid']for c in cs};gs=[g for g in m['guards']if g['label']in {u+':copper'for u in uids}];assert len(cs)==2 and len(gs)==1,'Expected one real two-branch pad';a.out.mkdir(parents=True,exist_ok=True)
d={k:m[k]for k in ['board_sha256','adapter_sources','aliases','rules']};d.update(contacts=cs,guards=gs,parent_model_sha256=sha(a.model),isolated_contact_fixture=True);(a.out/'model.json').write_text(json.dumps(d,indent=2)+'\n');shutil.copy2(a.model.parent/'routing.dsn',a.out/'routing.dsn');receipt={'schema':'f722-native-contact-fixture/v1','board_sha256':m['board_sha256'],'parent_model_sha256':sha(a.model),'generator_sha256':sha(__file__),'fixture_model_sha256':sha(a.out/'model.json'),'fixture_dsn_sha256':sha(a.out/'routing.dsn'),'pad':a.pad,'contacts':len(cs),'guards':len(gs),'adapter_sources':m['adapter_sources'],'route_search':False};(a.out/'fixture-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps({k:v for k,v in receipt.items()if k!='adapter_sources'}))
